text:
  block-size: 14px;
}

#msgIdentityPopup > menuitem[selected] {
  background-color: var(--autocomplete-popup-highlight-background);
  color: var(--autocomplete-popup-highlight-color);
}

#msgIdentity.has-custom-color {
  --icon-color: var(--selected-item-color);

  &[is="menulist-editable"]::part(label-box)::before {
    display: block;
    position: relative;
    content: "";
    inline-size: 6px;
    block-size: 6px;
    border-radius: 3px;
    margin-inline-end: 1px;
    background-color: var(--icon-color);
  }

  & #msgIdentityPopup > menuitem:not(:last-child) {
    --icon-color: var(--selected-item-color);

    &::before {
      display: block;
      position: relative;
      content: "";
      inline-size: 6px;
      block-size: 6px;
      border-radius: 3px;
      margin-inline: -3px 4px;
      background-color: var(--icon-color);
    }

    &[selected]::before {
      border-radius: 4px;
      border: 1px solid var(--autocomplete-popup-highlight-color);
    }
  }
